import { Contract, isAddress } from "ethers";
import { TARGET_CHAIN_ID } from "./chains.js";
// Both files are generated by the contracts project (npm run deploy:local /
// npm run export-abi). Add Sepolia addresses to deployments.json by hand after
// deploying with Remix, under the key "11155111".
import deployments from "./deployments.json";
import elementCardsAbi from "./abi/ElementCards.json";
import arenaAbi from "./abi/Arena.json";

const addresses = deployments[String(TARGET_CHAIN_ID)] ?? {};

export const CARDS_ADDRESS = addresses.ElementCards ?? "";
export const ARENA_ADDRESS = addresses.Arena ?? "";
export const contractsConfigured = isAddress(CARDS_ADDRESS) && isAddress(ARENA_ADDRESS);

// Pass a provider for free reads, or a signer for transactions.
export function getCardsContract(runner) {
  return new Contract(CARDS_ADDRESS, elementCardsAbi, runner);
}

export function getArenaContract(runner) {
  return new Contract(ARENA_ADDRESS, arenaAbi, runner);
}

// Solidity enums arrive as numbers. These arrays use the same order as the contracts.
export const ELEMENTS = ["Fire", "Water", "Wood"];
export const RARITIES = ["Common", "Rare", "Legendary"];
export const BATTLE_STATUS = ["None", "Open", "Joined", "Resolved", "Cancelled"];
